/**
 * ingredientSeed.ts
 * ─────────────────
 * A comprehensive library of 130+ popular soap & beauty-making ingredients,
 * ready to be bulk-imported into the local database. All ingredients start
 * as INACTIVE so the user's workspace isn't overwhelming — they toggle on
 * only what they actually use.
 *
 * Each entry includes:
 *  • name        — friendly display name
 *  • inci        — INCI / CTFA scientific name for back-label compliance
 *  • benefit     — one-line plain-English benefit description
 *  • isSoapBase  — true if essential for saponification (lye, main fats)
 *  • category    — visual grouping for the icon shown in the ingredient list
 */

import type { IngredientCategory } from '@/types';

export interface SeedIngredient {
  name: string;
  inci: string;
  benefit: string;
  isSoapBase: boolean;
  category: IngredientCategory;
  /** When true this ingredient is pre-activated in the user's workspace after seeding. */
  active?: boolean;
  /** Determines the COGS unit: 'weight' = grams, 'volume' = drops. */
  measurementType?: 'weight' | 'volume';
}

